        std::FILE* old = file_;
        file_ = nullptr;
        return !old || std::fclose(old) == 0;
    }
};
class ActiveScope {
    int& live_;
public:
    explicit ActiveScope(int& live) : live_(live) { ++live_; }
    ~ActiveScope() { --live_; }
    ActiveScope(const ActiveScope&) = delete;
    ActiveScope& operator=(const ActiveScope&) = delete;
};

