    const auto bytes = std::fread(buffer, 1, sizeof buffer, file.get());
    CHECK(std::string(buffer, bytes) == text);
    CHECK(file.close());
    int live{};
    try {
        ActiveScope scope{live};
        CHECK(live == 1);
        throw SimulatedFailure{};
    } catch (const SimulatedFailure&) {}
    CHECK(live == 0);
