auto make_counter(int initial) {
    return [value = initial]() mutable { return ++value; };
}

int main() {
    int cutoff{3};
    const auto fixed = [cutoff](int value) { return value >= cutoff; };
    const auto live = [&cutoff](int value) { return value >= cutoff; };
