    CHECK(add(2, 3) == 5 && add(2.0, 0.5) == 2.5);
    std::vector<int> data{1, 2, 3};
    std::transform(data.begin(), data.end(), data.begin(),
                   [](int value) { return value * value; });
    CHECK(data == std::vector<int>({1, 4, 9}));
    course::report();
}

